<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Motoboys | Burgues</title><link rel="icon" type="image/png" href="{{ asset('logoburguer.png') }}"><style>
:root{--yellow:#ffd21a;--ink:#111214;--muted:#686c75;--line:#e1e4e9;--paper:#f5f6f8}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:14px Inter,system-ui,-apple-system,"Segoe UI",sans-serif}button,input,select{font:inherit}button{cursor:pointer}.topbar{height:80px;background:#111;color:#fff}.nav{height:100%;max-width:1532px;margin:auto;padding:0 8px;display:flex;align-items:center;gap:38px}.brand{width:180px}.brand img{width:95px;height:68px;object-fit:contain}.links{display:flex;align-items:center;gap:26px;flex:1;height:100%}.links a{height:100%;display:flex;align-items:center;color:#eee;text-decoration:none;font-weight:650;padding:0 8px;border-bottom:3px solid transparent}.links a.active{color:var(--yellow);border-color:var(--yellow)}.exit{background:var(--yellow);border:0;border-radius:10px;padding:12px 22px;font-weight:750}main{max-width:1532px;margin:auto;padding:28px 8px}.heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px}h1{font-size:30px;margin:0 0 5px;letter-spacing:-1px}.muted{color:var(--muted);margin:0}.panel{background:white;border-radius:14px;padding:20px;margin-bottom:20px;box-shadow:0 4px 18px #10182808}.panel h2{font-size:22px;margin:0 0 4px}.panel-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px}.pill{background:#fff4d4;color:#936800;border-radius:9px;padding:9px 13px;font-size:12px;font-weight:700}.grid{display:grid;grid-template-columns:1.3fr 1fr 1fr 1fr;gap:14px 18px}.field label{display:block;font-weight:700;font-size:13px;margin-bottom:5px}.control{width:100%;height:42px;border:1px solid var(--line);border-radius:9px;background:white;padding:0 12px;outline:none}.control:focus{border-color:#d7a800;box-shadow:0 0 0 3px #ffd21a2b}.actions{grid-column:1/-1;display:flex;justify-content:flex-end;gap:9px}.btn{border:1px solid #e6b400;border-radius:10px;padding:11px 17px;background:white;color:#946800;font-weight:700;text-decoration:none}.btn.